import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageTimetable() {
  const [timetableData, setTimetableData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedGrade, setSelectedGrade] = useState('Grade 8');

  // Form States for Adding New Class
  const [grade, setGrade] = useState('Grade 8');
  const [day, setDay] = useState('Monday');
  const [timeSlot, setTimeSlot] = useState('');
  const [subject, setSubject] = useState('');
  const [teacher, setTeacher] = useState('');
  const [isAdding, setIsAdding] = useState(false);

  // Initial Sample Data for fallback
  const sampleData = [
    { id: 1, grade: 'Grade 8', day: 'Wednesday', time_slot: '2.45 PM - 4.45 PM', subject: 'English', teacher: 'Ranga Rajaguru' },
    { id: 2, grade: 'Grade 8', day: 'Saturday', time_slot: '2.15 PM - 4.15 PM', subject: 'Science', teacher: 'Ravindu Jayaweera' },
    { id: 3, grade: 'Grade 8', day: 'Tuesday', time_slot: '4.45 PM - 6.45 PM', subject: 'Mathematics', teacher: 'Buddhika Darshani' }
  ];

  const fetchTimetable = () => {
    setLoading(true);
    axios.get('http://localhost:8082/api/timetable')
      .then(res => {
        if (res.data && res.data.length > 0) {
          setTimetableData(res.data);
        } else {
          setTimetableData(sampleData);
        }
        setLoading(false);
      })
      .catch(() => {
        setTimetableData(sampleData);
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchTimetable();
  }, []);

  // Filter Data by Selected Grade
  const filteredData = timetableData.filter(
    item => item.grade && item.grade.toString().trim().toLowerCase() === selectedGrade.toString().trim().toLowerCase()
  );

  const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
  const dayHeaders = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

  const uniqueTimeSlots = [...new Set(filteredData.map(item => item.time_slot))].filter(Boolean);

  const getClassForSlot = (dayName, slot) => {
    return filteredData.find(
      item => item.day.toLowerCase() === dayName.toLowerCase() && item.time_slot === slot
    );
  };

  // Add New Schedule Handler
  const handleAddSchedule = (e) => {
    e.preventDefault();
    if (!timeSlot || !subject || !teacher) {
      alert('Please fill in all fields!');
      return;
    }

    const newItem = {
      id: Date.now(),
      grade,
      day,
      time_slot: timeSlot,
      subject,
      teacher
    };

    axios.post('http://localhost:8082/api/timetable', newItem)
      .then(() => {
        alert('✅ Class Scheduled Successfully!');
        fetchTimetable();
      })
      .catch(() => {
        // Fallback for Local state update if backend offline
        setTimetableData(prev => [...prev, newItem]);
        alert('✅ Class Scheduled Successfully (Local Update)!');
      });

    // Reset Form
    setTimeSlot('');
    setSubject('');
    setTeacher('');
    setIsAdding(false);
  };

  // Delete Schedule Handler
  const handleDeleteSlot = (id) => {
    if (window.confirm('Are you sure you want to delete this class schedule?')) {
      axios.delete(`http://localhost:8082/api/timetable/${id}`)
        .then(() => {
          fetchTimetable();
        })
        .catch(() => {
          setTimetableData(prev => prev.filter(item => item.id !== id));
        });
    }
  };

  return (
    <div style={styles.container}>
      {/* Top Header & Actions */}
      <div style={styles.headerRow}>
        <div>
          <h2 style={styles.pageTitle}>🗓️ Manage Class Timetable</h2>
          <p style={styles.subTitle}>Add, edit, and organize weekly class schedules for all grades.</p>
        </div>

        <button 
          onClick={() => setIsAdding(!isAdding)} 
          style={styles.addBtn}
        >
          {isAdding ? '✖ Close Form' : '➕ Add New Class Schedule'}
        </button>
      </div>

      {/* Add Class Form Modal / Panel */}
      {isAdding && (
        <form onSubmit={handleAddSchedule} style={styles.formCard}>
          <h3 style={{ margin: '0 0 15px 0', color: '#15803d', fontSize: '16px' }}>📝 Add New Class Schedule</h3>
          <div style={styles.formGrid}>
            <div>
              <label style={styles.label}>Select Grade</label>
              <select value={grade} onChange={e => setGrade(e.target.value)} style={styles.input}>
                <option value="Grade 6">Grade 6</option>
                <option value="Grade 7">Grade 7</option>
                <option value="Grade 8">Grade 8</option>
                <option value="Grade 9">Grade 9</option>
                <option value="Grade 10">Grade 10</option>
                <option value="Grade 11">Grade 11</option>
              </select>
            </div>

            <div>
              <label style={styles.label}>Select Day</label>
              <select value={day} onChange={e => setDay(e.target.value)} style={styles.input}>
                {days.map(d => <option key={d} value={d}>{d}</option>)}
              </select>
            </div>

            <div>
              <label style={styles.label}>Time Slot (e.g. 2.45 PM - 4.45 PM)</label>
              <input 
                type="text" 
                placeholder="2.45 PM - 4.45 PM" 
                value={timeSlot} 
                onChange={e => setTimeSlot(e.target.value)} 
                style={styles.input} 
                required 
              />
            </div>

            <div>
              <label style={styles.label}>Subject</label>
              <input 
                type="text" 
                placeholder="Mathematics / Science" 
                value={subject} 
                onChange={e => setSubject(e.target.value)} 
                style={styles.input} 
                required 
              />
            </div>

            <div>
              <label style={styles.label}>Teacher Name</label>
              <input 
                type="text" 
                placeholder="Mr. Perera" 
                value={teacher} 
                onChange={e => setTeacher(e.target.value)} 
                style={styles.input} 
                required 
              />
            </div>
          </div>

          <button type="submit" style={styles.saveBtn}>Save Schedule 💾</button>
        </form>
      )}

      {/* Filter Bar */}
      <div style={styles.filterRow}>
        <span style={{ fontWeight: 'bold', color: '#334155' }}>Filter by Grade: </span>
        {['Grade 6', 'Grade 7', 'Grade 8', 'Grade 9', 'Grade 10', 'Grade 11'].map(g => (
          <button
            key={g}
            onClick={() => setSelectedGrade(g)}
            style={{
              ...styles.filterBtn,
              backgroundColor: selectedGrade === g ? '#15803d' : '#ffffff',
              color: selectedGrade === g ? '#ffffff' : '#475569',
              borderColor: selectedGrade === g ? '#15803d' : '#cbd5e1'
            }}
          >
            {g}
          </button>
        ))}
      </div>

      {/* Timetable Table Card */}
      <div style={styles.card}>
        <h3 style={styles.title}>📅 Weekly Schedule ({selectedGrade})</h3>

        {loading ? (
          <div style={{ padding: '20px', textAlign: 'center' }}>Loading timetable...</div>
        ) : (
          <div style={{ overflowX: 'auto' }}>
            <table style={styles.table}>
              <thead>
                <tr>
                  <th style={{ ...styles.th, width: '150px' }}>Time Slot</th>
                  {dayHeaders.map((d, idx) => (
                    <th key={idx} style={styles.th}>{d}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {uniqueTimeSlots.length > 0 ? (
                  uniqueTimeSlots.map((slot, sIdx) => (
                    <tr key={sIdx} style={styles.tr}>
                      <td style={styles.timeTd}>{slot}</td>
                      {days.map((d, dIdx) => {
                        const classItem = getClassForSlot(d, slot);
                        return (
                          <td key={dIdx} style={styles.td}>
                            {classItem ? (
                              <div style={styles.classBox}>
                                <div style={styles.subjectName}>{classItem.subject}</div>
                                <div style={styles.teacherName}>{classItem.teacher}</div>
                                <button 
                                  onClick={() => handleDeleteSlot(classItem.id)} 
                                  style={styles.deleteBtn}
                                  title="Remove Schedule"
                                >
                                  🗑️ Delete
                                </button>
                              </div>
                            ) : (
                              <span style={styles.dash}>-</span>
                            )}
                          </td>
                        );
                      })}
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="8" style={{ padding: '30px', textAlign: 'center', color: '#94a3b8' }}>
                      No classes scheduled for {selectedGrade}. Click <b>"Add New Class Schedule"</b> to add one.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

const styles = {
  container: { padding: '20px', backgroundColor: '#f8fafc', minHeight: '100vh' },
  headerRow: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', flexWrap: 'wrap', gap: '15px' },
  pageTitle: { margin: 0, color: '#0f172a', fontSize: '24px', fontWeight: '800' },
  subTitle: { margin: '4px 0 0 0', color: '#64748b', fontSize: '14px' },
  addBtn: { backgroundColor: '#15803d', color: '#ffffff', border: 'none', padding: '12px 20px', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '14px', boxShadow: '0 2px 8px rgba(21, 128, 61, 0.2)' },
  formCard: { backgroundColor: '#ffffff', padding: '20px', borderRadius: '12px', border: '1px solid #bbf7d0', marginBottom: '20px', boxShadow: '0 4px 15px rgba(0,0,0,0.04)' },
  formGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '15px', marginBottom: '15px' },
  label: { fontSize: '12px', fontWeight: 'bold', color: '#334155', display: 'block', marginBottom: '5px' },
  input: { width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '13px', boxSizing: 'border-box' },
  saveBtn: { backgroundColor: '#3ea006', color: '#ffffff', border: 'none', padding: '10px 24px', borderRadius: '6px', fontWeight: 'bold', cursor: 'pointer', fontSize: '14px' },
  filterRow: { display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '20px', flexWrap: 'wrap' },
  filterBtn: { border: '1px solid', padding: '6px 16px', borderRadius: '20px', cursor: 'pointer', fontSize: '13px', fontWeight: 'bold', transition: '0.2s' },
  card: { backgroundColor: '#ffffff', borderRadius: '12px', padding: '24px', boxShadow: '0 4px 20px rgba(0, 0, 0, 0.03)', border: '1px solid #e2e8f0' },
  title: { margin: '0 0 20px 0', color: '#1e293b', fontSize: '18px', fontWeight: '700' },
  table: { width: '100%', borderCollapse: 'collapse', fontSize: '13px' },
  th: { backgroundColor: '#f8fafc', color: '#64748b', fontWeight: '600', padding: '12px 8px', textAlign: 'center', borderBottom: '1px solid #e2e8f0' },
  tr: { borderBottom: '1px solid #f1f5f9' },
  timeTd: { padding: '16px 8px', fontWeight: '700', color: '#334155', textAlign: 'left', fontSize: '12px' },
  td: { padding: '10px 6px', textAlign: 'center', verticalAlign: 'middle' },
  dash: { color: '#cbd5e1', fontWeight: 'bold' },
  classBox: { backgroundColor: '#f0fdf4', border: '1px solid #bbf7d0', borderRadius: '8px', padding: '8px', position: 'relative' },
  subjectName: { fontWeight: 'bold', color: '#15803d', fontSize: '12px' },
  teacherName: { color: '#64748b', fontSize: '11px', marginTop: '2px', marginBottom: '4px' },
  deleteBtn: { backgroundColor: '#fee2e2', color: '#991b1b', border: 'none', padding: '3px 8px', borderRadius: '4px', fontSize: '10px', fontWeight: 'bold', cursor: 'pointer', marginTop: '4px' }
};
